CREATE TABLE store_identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1),store_id TEXT NOT NULL,installation_id TEXT NOT NULL,data_dir TEXT NOT NULL);
CREATE TABLE config_revisions(id INTEGER PRIMARY KEY AUTOINCREMENT,schema_version INTEGER NOT NULL CHECK(schema_version=1),body TEXT NOT NULL CHECK(json_valid(body)),created_at TEXT NOT NULL);
CREATE TRIGGER immutable_config_update BEFORE UPDATE ON config_revisions BEGIN SELECT RAISE(ABORT,'immutable configuration'); END;
CREATE TRIGGER immutable_config_delete BEFORE DELETE ON config_revisions BEGIN SELECT RAISE(ABORT,'immutable configuration'); END;
CREATE TABLE settings_head(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision_id INTEGER NOT NULL REFERENCES config_revisions(id));
CREATE TABLE selected_repositories(revision_id INTEGER NOT NULL REFERENCES config_revisions(id),repository_id TEXT NOT NULL,PRIMARY KEY(revision_id,repository_id));
CREATE TABLE cloud_targets(revision_id INTEGER NOT NULL REFERENCES config_revisions(id),target_id TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(revision_id,target_id));
CREATE TABLE schedule_config(revision_id INTEGER PRIMARY KEY REFERENCES config_revisions(id),body TEXT NOT NULL CHECK(json_valid(body)));
CREATE TABLE managed_roots(id TEXT PRIMARY KEY,path TEXT NOT NULL,filesystem_id TEXT NOT NULL,store_id TEXT NOT NULL,installation_id TEXT NOT NULL,data_dir TEXT NOT NULL,generation INTEGER NOT NULL CHECK(generation>0),active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE UNIQUE INDEX single_active_root ON managed_roots(active) WHERE active=1;
CREATE TABLE backup_runs(id TEXT PRIMARY KEY,trigger TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('preparing','running','cancelling','succeeded','partial','failed','cancelled','interrupted')),config_revision_id INTEGER NOT NULL REFERENCES config_revisions(id),intent TEXT NOT NULL CHECK(json_valid(intent)),started_at TEXT NOT NULL,finished_at TEXT,error_code TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX single_active_run ON backup_runs((1)) WHERE state IN('preparing','running','cancelling');
CREATE TRIGGER immutable_run_intent BEFORE UPDATE OF intent,config_revision_id,trigger,started_at ON backup_runs BEGIN SELECT RAISE(ABORT,'immutable intent'); END;
CREATE TABLE snapshots(id TEXT PRIMARY KEY,repository_id TEXT NOT NULL,provider TEXT NOT NULL,root_id TEXT NOT NULL REFERENCES managed_roots(id),format_version INTEGER NOT NULL CHECK(format_version>0),relative_path TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('staging','ready','missing','corrupt','abandoned','deleting','deleted')),publication_state TEXT NOT NULL CHECK(publication_state IN('not_published','published','published_durability_uncertain','outcome_unknown_requires_reconciliation')),sha256 TEXT NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes>=0),created_at TEXT NOT NULL,verification TEXT NOT NULL CHECK(json_valid(verification)),UNIQUE(root_id,relative_path));
CREATE TABLE repository_tasks(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES backup_runs(id),repository_id TEXT NOT NULL,provider TEXT NOT NULL,operation_id TEXT NOT NULL,stage TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('pending','succeeded','failed','cancelled','interrupted','empty_repository')),attempt INTEGER NOT NULL CHECK(attempt>0),snapshot_id TEXT REFERENCES snapshots(id),artifact_id TEXT NOT NULL,artifact_path TEXT NOT NULL,publication_state TEXT NOT NULL,cloud_outcome TEXT NOT NULL,error_code TEXT NOT NULL,UNIQUE(run_id,repository_id));
CREATE TABLE pins(snapshot_id TEXT PRIMARY KEY REFERENCES snapshots(id),created_at TEXT NOT NULL);
CREATE TABLE leases(id TEXT PRIMARY KEY,snapshot_id TEXT NOT NULL REFERENCES snapshots(id),owner_id TEXT NOT NULL,operation_id TEXT NOT NULL,acquired_at TEXT NOT NULL,expires_at TEXT);
